mapper.select:
select BUILDING_ID, PRJ_LEASE_ID, BUILDING_STRUCTURE, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'FACTORY_BUILDING_STRUCTURE' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb.VALUE= BUILDING_STRUCTURE ) BUILDING_STRUCTURE_N, BUILDING_FACILITY, WORKSHOP_LAYOUT, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'CARROOM_DESIGN' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb.VALUE= WORKSHOP_LAYOUT ) WORKSHOP_LAYOUT_N, WORKSHOP_CLEAN_FREQUENCY, CLEAN_HOURS, WORKSHOP_SAFE_FLAG, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'SYS.YES_NO' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb.VALUE= WORKSHOP_SAFE_FLAG ) WORKSHOP_SAFE_FLAG_N from prj_lease_factory_building
1=1
AND prj_lease_id = #{prjLeaseId}
